# Grok Bot environment backup

Read these from memory first. If any is missing, run the getting-started skill.
- `OWNER_LABEL`: the label for the backup folder, for example the owner's email.
- `BACKUP_DIR`: `/workspace/<backup-dir>`.
- `BACKUP_TZ`: the owner's IANA time zone.
- Backup Drive folder id, run time, and retention in weeks (default 8).

Never copy or upload passwords, tokens, cookies, login files, keychain items, secret files, or browser profiles.

## 1. Make sure the script exists
If `$BACKUP_DIR/run-backup.sh` is missing, recreate it exactly from the block below and `chmod +x` it. If it exists and differs, copy it to `run-backup.sh.bak-YYYY-MM-DD` before replacing it.

What it does:
- Exports global, per-bot and profile settings, plus each bot's automations, attachments and assets.
- Dumps each bot's store.db to JSON read-only. Any field whose name contains key, secret, token, password or cookie is blanked, including inside hex-encoded JSON.
- Copies skills, the plugin cache, software lists, shell dotfiles and a home-folder listing that leaves out the browser profile.
- Writes `roster.md`, and includes the newest device roster from `$BACKUP_DIR/device-roster/`.
- Fails the run if a secret file or a sensitive field slips through.
- Never overwrites an existing archive. For a test or a second run on the same day, set `ARCHIVE_NAME=<name>.tar.gz`.

```bash
#!/usr/bin/env bash
# Rebuild the Grok Bot environment backup. Usage: OWNER_LABEL=<label> BACKUP_DIR=/workspace/<backup-dir> BACKUP_TZ=<IANA zone> ./run-backup.sh [YYYY-MM-DD]
# Excludes: box-secrets.json, host-secrets.json, gateway.json, chrome-profile, cookies/tokens.
set -euo pipefail
export TZ="${BACKUP_TZ:-UTC}"
DATE="${1:-$(date +%F)}"; USERNAME="${OWNER_LABEL:?set OWNER_LABEL}"
ROOT="${BACKUP_DIR:?set BACKUP_DIR}"; B="$ROOT/$USERNAME"; S="${AGENT_DATA:-/home/box/agent-data}"
README_KEEP=""; [ -f "$B/README.md" ] && README_KEEP=$(mktemp) && cp "$B/README.md" "$README_KEEP"
rm -rf "$B"; mkdir -p "$B"/{agent,skills,plugins,software,box}
cp "$S/settings.json" "$B/agent/global-settings.json"; cp "$S/agents/active-agent.json" "$B/agent/"
for A in "$S"/agents/*/; do id=$(basename "$A"); D="$B/agent/$id"; mkdir -p "$D"
  cp "$A"/profile.json "$A"/settings.json "$D/" 2>/dev/null || true
  for d in attachments automations assets; do [ -d "$A/$d" ] && cp -r "$A/$d" "$D/"; done
  [ -f "$A/store.db" ] && python3 - "$A/store.db" "$D/store-export.json" <<'PY'
import sqlite3,json,sys
c=sqlite3.connect(f'file:{sys.argv[1]}?mode=ro',uri=True); out={}
for (t,) in c.execute("select name from sqlite_master where type='table'"):
    out[t]=[list(r) for r in c.execute(f'select * from "{t}"')]
import re
SENS=re.compile(r'(?i)key|secret|token|password|cookie')
def red(o):
    if isinstance(o,dict): return {k:('[redacted]' if SENS.search(k) else red(v)) for k,v in o.items()}
    if isinstance(o,list): return [red(v) for v in o]
    if isinstance(o,str):
        try:
            j=json.loads(o)
            if isinstance(j,(dict,list)): return json.dumps(red(j))
        except Exception: pass
    return o
for r in out.get('kv',[]):
    if SENS.search(str(r[0])): r[1]='[redacted]'; continue
    try:
        d=red(json.loads(bytes.fromhex(r[1]).decode())); r[1]=json.dumps(d).encode().hex(); r.append(d)
    except Exception: pass
out={t:red(rows) for t,rows in out.items()}
json.dump(out,open(sys.argv[2],'w'),indent=1,default=str)
PY
done
cp -r "$S/managed-skills/skills" "$B/skills/managed"
[ -d /home/box/.cursor/skills-cursor ] && cp -r /home/box/.cursor/skills-cursor "$B/skills/cursor-skills"
for p in "$S"/plugins/cache/*/*/; do n=$(basename "$p"); mkdir -p "$B/plugins/$n"; cp -r "$p"*/. "$B/plugins/$n/"; done
cp "$S/plugin-skills/cache.json" "$B/plugins/plugin-skills-cache.json"
dpkg-query -W > "$B/software/apt-packages.txt"; pip list --format=freeze > "$B/software/pip.txt" 2>/dev/null || true
npm ls -g --depth=0 > "$B/software/npm-global.txt" 2>&1 || true
{ uname -a; cat /etc/os-release; python3 -V; node -v 2>&1 || true; } > "$B/software/system.txt"
cp /home/box/.bashrc /home/box/.profile "$B/box/"; cp -r /home/box/reference "$B/box/"
(cd /home/box && find . -maxdepth 4 -not -path './chrome-profile/*' -not -path './.cache/*' | sort) > "$B/box/home-tree.txt"
[ -f "$ROOT/connectors.md" ] && cp "$ROOT/connectors.md" "$B/" || echo "# Connector inventory: refresh from GetMcpServerStatus" > "$B/connectors.md"
if [ -n "$README_KEEP" ]; then sed "s/^Created .* by Grok Bot/Created $DATE at $(date '+%-I:%M %p %Z') by Grok Bot/" "$README_KEEP" > "$B/README.md"; rm "$README_KEEP"; fi
# device roster: the routine downloads the newest grokbot-roster-*.md from the backup Drive folder into $ROOT/device-roster (this script cannot reach Drive)
DEVR=$(ls -1 "$ROOT"/device-roster/grokbot-roster-*.md 2>/dev/null | sort | tail -1 || true)
if [ -n "$DEVR" ]; then
  sed -E 's/((api[_-]?key|secret|token|password|cookie)[[:space:]]*[:=][[:space:]]*)[^[:space:]]+/\1[redacted]/Ig' "$DEVR" > "$B/$(basename "$DEVR")"
  NOTE="Device roster included: $(basename "$DEVR") (from the Drive backup folder)."
else NOTE="Device roster missing: no grokbot-roster-*.md was found in the Drive backup folder. Run extract-grokbot-roster.sh on the Mac and upload the result."; fi
[ -f "$B/README.md" ] && sed -i '/^## Device roster$/,$d' "$B/README.md"
[ -f "$B/README.md" ] || echo "# Grok Bot backup $DATE" > "$B/README.md"
printf '\n## Device roster\n%s\n' "$NOTE" >> "$B/README.md"
# safety check: abort if a secret file slipped in
if find "$B" \( -name '*secrets*.json' -o -name gateway.json -o -iname 'Cookies*' -o -iname 'Login Data*' \) | grep -q .; then echo "secret file found, aborting" >&2; exit 1; fi
# roster.md: bot roster from global settings, profile.json, settings.json, store.db (read-only); unknowns stated, never guessed
python3 - "$S" "$B/roster.md" <<'ROSTER'
import json,os,re,sys,sqlite3,glob,datetime
from zoneinfo import ZoneInfo
S,outp=sys.argv[1],sys.argv[2]; TZ=ZoneInfo(os.environ.get('TZ','UTC'))
SENS=re.compile(r'(?i)key|secret|token|password|cookie')
def ld(p):
    try: return json.load(open(p))
    except Exception: return {}
def fmt(ms): return datetime.datetime.fromtimestamp(ms/1000,TZ).strftime('%Y-%m-%d %-I:%M %p %Z') if ms else None
def find(d,names):
    if isinstance(d,dict):
        for k,v in d.items():
            if k in names: return v
            r=find(v,names)
            if r is not None: return r
    return None
g=ld(f'{S}/settings.json'); bots=[]
for A in sorted(glob.glob(f'{S}/agents/*/')):
    aid=os.path.basename(A.rstrip('/')); p=ld(A+'profile.json'); st=ld(A+'settings.json'); meta={}; unread={}; lastt=0
    try:
        c=sqlite3.connect(f'file:{A}store.db?mode=ro',uri=True)
        for k,v in c.execute('select key,value from kv'):
            try: v=bytes.fromhex(v).decode()
            except Exception: pass
            try: v=json.loads(v)
            except Exception: pass
            if k=='metadata': meta=v if isinstance(v,dict) else {}
            if k=='unreadState': unread=v if isinstance(v,dict) else {}
    except Exception: pass
    try:
        for row in sqlite3.connect(f'file:{A}store.db?mode=ro',uri=True).execute('select * from transcript_entries'):
            for x in row:
                try: lastt=max(lastt,json.loads(x).get('timestampMs',0))
                except Exception: pass
    except Exception: pass
    voice=find(p,{'voice','voiceId','voiceName'}) or find(st,{'voice','voiceId','voiceName'})
    created=meta.get('createdAt'); last=unread.get('lastActivityAt') or lastt
    bots.append(dict(id=aid,name=p.get('name') or meta.get('name') or '(name not found)',desc=(p.get('description') or '').strip(),
        voice=voice,created=fmt(created),last=fmt(last),lastsrc='unreadState' if unread.get('lastActivityAt') else ('latest transcript entry' if lastt else None)))
sections=find(g,{'sidebarSections','sections','sidebar'}); pinned=find(g,{'pinnedAgentIds','pinned','pinnedAgents'})
now=datetime.datetime.now(TZ).strftime('%Y-%m-%d %-I:%M %p %Z')
L=[f'# Bot roster\n',f'Extracted {now}. Bots: {len(bots)}. Empty descriptions: {sum(1 for b in bots if not b["desc"])}.\n',
   '\n## Sidebar\n']
names={b['id']:b['name'] for b in bots}
if sections:
    for s in sections if isinstance(sections,list) else []:
        ids=s.get('agentIds',[]) if isinstance(s,dict) else []
        L.append(f"- {s.get('name','(unnamed)') if isinstance(s,dict) else s}: "+(', '.join(names.get(i,i) for i in ids) or '(no bots)')+'\n')
else: L.append('- Sidebar sections: not available on the box (use the device roster from the Mac).\n')
L.append('- Pinned bots: '+(', '.join(names.get(i,i) for i in pinned) if pinned else 'not available on the box (use the device roster from the Mac).')+'\n')
for b in bots:
    L.append(f"\n## {b['name']}"+(f" (voice: {b['voice']})" if b['voice'] else '')+'\n')
    L.append(f"- Id: {b['id']}\n- Voice: {b['voice'] or 'not set / not found on the box'}\n")
    L.append(f"- Created: {b['created'] or 'not available'}\n- Last activity: "+(f"{b['last']} (from {b['lastsrc']})" if b['last'] else 'not available (no activity timestamp on the box)')+'\n')
    L.append('- Description: '+(b['desc'] if b['desc'] else '_Description is empty._')+'\n')
txt=''.join(L); txt=re.sub(r'(?i)((?:api[_-]?key|secret|token|password|cookie)\s*[:=]\s*)\S+',r'\1[redacted]',txt)
open(outp,'w').write(txt)
ROSTER
python3 -c "import re,sys;sys.exit(1 if re.search(r'(?i)(api[_-]?key|secret|token|password|cookie)\s*[:=]\s*(?!\[redacted\])\S',open(sys.argv[1]).read()) else 0)" "$B/roster.md" || { echo "secret value in roster.md, aborting" >&2; exit 1; }
# secret-field check on store dumps: fail if any sensitive field still has a value (plain or hex-encoded JSON)
python3 - "$B" <<'CHK'
import json,re,sys,glob
SENS=re.compile(r'(?i)key|secret|token|password|cookie'); bad=[]
def scan(o,f,path):
    if isinstance(o,dict):
        for k,v in o.items():
            if SENS.search(k) and v not in ('[redacted]','',None): bad.append(f'{f}:{path}/{k}')
            scan(v,f,path+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): scan(v,f,f'{path}[{i}]')
    elif isinstance(o,str):
        for dec in (lambda x:x, lambda x:bytes.fromhex(x).decode()):
            try:
                j=json.loads(dec(o))
                if isinstance(j,(dict,list)): scan(j,f,path+'<decoded>'); break
            except Exception: pass
for f in glob.glob(sys.argv[1]+'/agent/*/store-export.json'): scan(json.load(open(f)),f,'')
if bad: print('secret fields remain:',*bad,sep='\n',file=sys.stderr); sys.exit(1)
print('secret-field check passed')
CHK
cd "$ROOT"; ARCHIVE="${ARCHIVE_NAME:-grokbot-backup-$USERNAME-$DATE.tar.gz}"; [ -e "$ARCHIVE" ] && { echo "archive $ARCHIVE exists, refusing to overwrite" >&2; exit 1; }; tar czf "$ARCHIVE" "$USERNAME"
ls -la "$ROOT/$ARCHIVE"
```

## 2. Nightly steps
1. **Device roster:** use the Google Drive connector to find the newest `grokbot-roster-*.md` in the backup folder itself, not in a dated subfolder. Download it to `$BACKUP_DIR/device-roster/`. If there isn't one, continue; the script notes in the README that it's missing.
2. **Connector status:** refresh `$BACKUP_DIR/connectors.md` with a table of connector names, types and current status (connected, not connected or error). Include no secrets or account tokens.
3. **Run the script:** `OWNER_LABEL=… BACKUP_DIR=… BACKUP_TZ=… $BACKUP_DIR/run-backup.sh`. If it exits non-zero, stop and tell the owner why.
4. **Markdown exports:** write these in `$BACKUP_DIR/$OWNER_LABEL/`, then rebuild the archive with `ARCHIVE_NAME=grokbot-backup-$OWNER_LABEL-YYYY-MM-DD-exports.tar.gz`:
   - `bot-exports.md`: for every bot, its routine prompts, memories and sidebar section name, or "not available" when the box doesn't have them.
   - `transcripts-YYYY-MM-DD.md`: today's chat transcript for every bot, using the transcript tool if you have one, or each store.db's `transcript_entries` table otherwise.
   - Redact anything that looks like a secret (bearer tokens, JWTs, API keys, long hex strings, `token:`/`password:` values) to `[redacted]`, then check that none remain before uploading.
5. **Upload:** in the backup Drive folder, create `YYYY-MM-DD` if it doesn't exist. Upload the archive, README.md and the Markdown files into it. Add files; never overwrite. If a name is already taken, add `-v2`.
6. **Prune:** delete only dated `YYYY-MM-DD` folders in the backup folder that are older than the retention period. Never delete anything else.
7. **Report:** message the owner only when a run fails or something needs their attention, such as a missing device roster for several nights or a disconnected connector.

## 3. Device roster from the owner's Mac
Sidebar sections, pinned bots, voices and local permission settings live only in the desktop app. Offer the owner this script. They run it in Terminal with `bash extract-grokbot-roster.sh` (add `--debug` to print each decoded cache name and its field names and types, never values; it needs Python 3), check the resulting `grokbot-roster-YYYY-MM-DD.md`, and upload it to the backup folder itself, not a dated subfolder. It only reads files, never reads chat transcripts, skips cookie, login, token, secret and keychain files, redacts secret-looking values, and lists anything it couldn't find. Auto-review settings are kept in the Grok Bot account, not on the Mac, so the server backup covers them.

```bash
#!/usr/bin/env bash
# Export a Grok Bot roster from the desktop app's local cache on macOS. Read-only.
# Usage: bash extract-grokbot-roster.sh [--debug] [output-dir]   -> grokbot-roster-YYYY-MM-DD.md
# --debug prints each decoded blob name and its value shape (field names and types, never values) to stderr.
# Never opens cookies, Login Data, token/secret/credential files, transcripts, or the keychain. Secret-looking values are redacted.
set -euo pipefail
DEBUG=0; OUT_DIR="$PWD"; for a in "$@"; do case "$a" in --debug) DEBUG=1;; *) OUT_DIR="$a";; esac; done; command -v python3 >/dev/null || { echo "python3 required (xcode-select --install)" >&2; exit 1; }
exec python3 - "$OUT_DIR" "$DEBUG" <<'PY'
import os,sys,json,re,sqlite3,datetime,glob,base64,gzip,zlib,struct
out_dir=sys.argv[1]; DEBUG=sys.argv[2]=='1'; H=os.path.expanduser('~')
ROOTS=[f'{H}/.grokbot']+glob.glob(f'{H}/Library/Application Support/*rok*ot*')+glob.glob(f'{H}/Library/Application Support/*rokbot*')
ROOTS=sorted({r for r in ROOTS if os.path.isdir(r)})
SKIP_NAME=re.compile(r'(?i)\.transcript\.|weekly-usage|sand-secrets|gateway-descriptor|local-exec-daemon|trust tokens|cookie|login data|token|secret|credential|keychain|password|passkey|web data|\.pem$|\.key$|\.p12$')
SKIP_DIR=re.compile(r'(?i)^(cache|code cache|gpucache|dawn.*cache|blob_storage|service worker|crashpad|logs?|node_modules|extensions|local storage|session storage|indexeddb|partitions|trust tokens)$')
SENS_KEY=re.compile(r'(?i)key|secret|token|password|cookie|credential|auth|session')
SENS_VAL=re.compile(r'(?i)(bearer\s+\S+|eyJ[\w-]{10,}\.[\w-]+\.[\w-]+|\b(sk|pk|xox[abp]|ghp|gho)[-_][\w-]{10,}|[0-9a-f]{40,})')
def red(s): return SENS_VAL.sub('[redacted]',str(s))
docs=[]  # (source, obj)
def addjson(src,txt):
    try: o=json.loads(txt)
    except Exception:
        try: o=json.loads(bytes.fromhex(txt).decode())
        except Exception: return
    if isinstance(o,(dict,list)): docs.append((src,o))
scanned=[]
SETTINGS=f'{H}/.grokbot/settings.json'; local_settings={}
try:
    local_settings=json.load(open(SETTINGS,encoding='utf-8')); scanned.append(SETTINGS)
    print(f'read {SETTINGS} ({os.path.getsize(SETTINGS)} bytes)',file=sys.stderr)
except FileNotFoundError: print(f'{SETTINGS} not found',file=sys.stderr)
except Exception as e: print(f'could not read {SETTINGS}: {e}',file=sys.stderr)
def b32name(f):
    n=f[:-5] if f.endswith('.blob') else f
    try: return base64.b32decode(n.upper()+'='*(-len(n)%8)).decode('utf-8')
    except Exception: return None
def decode_blob(raw):
    tries=[('json',lambda b:b),('gzip',gzip.decompress),('zlib',zlib.decompress),('raw-deflate',lambda b:zlib.decompress(b,-15))]
    for k in (1,2,4,8):
        tries.append((f'{k}-byte prefix',lambda b,k=k:b[k:]))
        tries.append((f'{k}-byte prefix+gzip',lambda b,k=k:gzip.decompress(b[k:])))
        tries.append((f'{k}-byte prefix+zlib',lambda b,k=k:zlib.decompress(b[k:])))
    for name,fn in tries:
        try:
            o=json.loads(fn(raw).decode('utf-8'))
            if isinstance(o,(dict,list)): return name,o
        except Exception: pass
    return None,None
for R in ROOTS:
    for d,dirs,files in os.walk(R):
        dirs[:]=[x for x in dirs if not SKIP_DIR.match(x) and not SKIP_NAME.search(x)]
        for f in files:
            p=os.path.join(d,f)
            if SKIP_NAME.search(f) or f.startswith('Singleton') or os.path.islink(p) or not os.path.isfile(p): continue
            try:
                if os.path.getsize(p)>50_000_000: continue
            except OSError: continue
            if p==SETTINGS: continue
            if f.endswith('.blob') and os.path.basename(d)=='sand-client-persistence':
                nm=b32name(f); sz=os.path.getsize(p)
                print(f'blob {nm or "(undecodable name: "+f+")"} {sz} bytes',file=sys.stderr)
                if nm is None or SKIP_NAME.search(nm): print('  skipped (secret-looking or undecodable name)',file=sys.stderr); continue
                fmt_,o=decode_blob(open(p,'rb').read())
                if o is None: print('  could not decode as JSON/gzip/zlib/prefixed',file=sys.stderr); continue
                print(f'  format: {fmt_}',file=sys.stderr)
                if DEBUG:
                    def shape(x,d=0):
                        if d>3: return '...'
                        if isinstance(x,dict): return '{'+', '.join(f'{k}: {shape(v,d+1)}' for k,v in list(x.items())[:25])+'}'
                        if isinstance(x,list): return f'list[{len(x)}] of '+(shape(x[0],d+1) if x else 'nothing')
                        return type(x).__name__
                    tgt=o.get('value',o) if isinstance(o,dict) else o
                    print(f'  [debug] {nm}: value shape: {shape(tgt)}',file=sys.stderr)
                if isinstance(o,dict) and 'value' in o and 'schemaVersion' in o: o=o['value']
                docs.append((f'blob:{nm}',o)); scanned.append(p); continue
            if f=='Preferences' or f.endswith('.json'):
                try: addjson(p,open(p,encoding='utf-8',errors='ignore').read()); scanned.append(p)
                except Exception: pass
            elif re.search(r'\.(db|sqlite3?)$',f):
                try:
                    c=sqlite3.connect(f'file:{p}?mode=ro&immutable=1',uri=True); scanned.append(p)
                    for (t,) in c.execute("select name from sqlite_master where type='table'"):
                        if SENS_KEY.search(t): continue
                        cols=[r[1] for r in c.execute(f'pragma table_info("{t}")')]
                        for row in c.execute(f'select * from "{t}" limit 20000'):
                            rk=dict(zip(cols,row))
                            for k,v in rk.items():
                                if isinstance(v,bytes):
                                    try: v=v.decode()
                                    except Exception: continue
                                if isinstance(v,str) and len(v)>1:
                                    n=len(docs); addjson(f'{p}:{t}',v)
                                    if len(docs)>n and len(cols)<=3:
                                        other=[x for x in row if isinstance(x,str) and x!=v]
                                        if other: docs[-1]=(docs[-1][0],{'__kvkey':other[0],'value':docs[-1][1]})
                except Exception as e: print(f'skip {p}: {e}',file=sys.stderr)
def walk(o,path=()):
    yield path,o
    if isinstance(o,dict):
        for k,v in o.items():
            if not SENS_KEY.search(str(k)): yield from walk(v,path+(k,))
    elif isinstance(o,list):
        for i,v in enumerate(o): yield from walk(v,path+(i,))
ID=re.compile(r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
bots={}; sections=None; pinned=None; perm={}; found_src={}
def g(d,*ks):
    for k in ks:
        if isinstance(d,dict) and d.get(k) not in (None,''): return d[k]
def ts(v):
    if v in (None,'',0): return None
    try:
        if isinstance(v,(int,float)): v=v/1000 if v>1e11 else v; return datetime.datetime.fromtimestamp(v).astimezone()
        return datetime.datetime.fromisoformat(str(v).replace('Z','+00:00')).astimezone()
    except Exception: return None
for src,o in docs:
    for path,v in walk(o):
        if not isinstance(v,dict): continue
        aid=g(v,'agentId','botId','id')
        if isinstance(aid,str) and ID.match(aid) and (g(v,'name','displayName','description','voice','createdAt') is not None):
            b=bots.setdefault(aid,{'id':aid,'src':set()}); b['src'].add(src)
            for f,ks in {'name':('name','displayName'),'description':('description',),'voice':('voice','voiceId','voiceName'),
                         'created':('createdAt','created_at','created'),'last':('lastActivityAt','lastMessageAt','updatedAt','lastActiveAt'),
                         'pinned':('pinned','isPinned'),'section':('sectionId','folderId','groupId')}.items():
                x=g(v,*ks)
                if x is not None and f not in b: b[f]=x
                if f=='last' and x and ts(x) and (not ts(b.get('last')) or ts(x)>ts(b['last'])): b['last']=x
        for k in ('sidebarSections','sections','sidebarGroups','folders'):
            if sections is None and isinstance(v.get(k),list) and v[k]: sections=v[k]; found_src['sections']=src
        for k in ('pinnedAgentIds','pinnedBotIds','pinned','pinnedAgents'):
            if pinned is None and isinstance(v.get(k),list): pinned=v[k]; found_src['pinned']=src
def flat(o,pre=''):
    if isinstance(o,dict):
        for k,v in o.items(): yield from flat(v,f'{pre}{k}.')
    else: yield pre[:-1],o
for k,v in flat(local_settings):
    lk=k.lower().replace('_','').replace('-','')
    if re.search(r'secret|token|password|cookie|credential',lk): continue
    if 'permission' in lk and 'Tool permission level' not in perm and not isinstance(v,(dict,list)): perm['Tool permission level']=f'{v} ({k})'
if DEBUG and local_settings: print('  [debug] settings.json flattened keys: '+', '.join(k for k,_ in flat(local_settings)),file=sys.stderr)
for src,o in docs:
    if src.endswith('.roster.last-roster') and isinstance(o,dict):
        for r in o.get('rows') or []:
            if not isinstance(r,dict) or not r.get('id'): continue
            b=bots.setdefault(r['id'],{'id':r['id'],'src':set()})
